fn solve(s: Vec<char>) -> Vec<char> {
    // Prepare a result vector with capacity for 19 input chars + 1 newline
    let mut result = Vec::with_capacity(s.len() + 1);

    // Map each comma to a space, keep letters as is
    for c in s {
        if c == ',' {
            result.push(' ');
        } else {
            result.push(c);
        }
    }

    // Append the newline character
    result.push('\n');
    result
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_solve_basic() {
        // "hello,world,xxxxx" -> "hello world xxxxx\n"
        let input: Vec<char> = "hello,world,abcde".chars().collect();
        let output = solve(input);
        let expected: Vec<char> = "hello world abcde\n".chars().collect();
        assert_eq!(output, expected);
    }

    #[test]
    fn test_all_commas() {
        // 19 commas -> 19 spaces + newline
        let input: Vec<char> = vec![','; 19];
        let output = solve(input);
        let mut expected = vec![' '; 19];
        expected.push('\n');
        assert_eq!(output, expected);
    }

    #[test]
    fn test_no_commas() {
        // 19 letters -> same letters + newline
        let input: Vec<char> = "abcdefghijklmnopqrs".chars().collect(); // 19 letters
        let output = solve(input.clone());
        let mut expected = input;
        expected.push('\n');
        assert_eq!(output, expected);
    }
}